function buildLandHousingGuidance(p){
 const b=p.building,a=b.answers,c=getAdvisoryConfig(b.group,b.type),checks=[...c.baseChecks],questions=getQuestionsFor(b.group,b.type,a),blocks=criticalAnswers(b),decisions=[];
 let models=[],why='',next='دامنه کار، اختیار زمین، تعهدات شبکه‌ها و مرجع تحویل را مستند کنید، سپس هزینه، منبع پول و سازوکار پرداخت بررسی شود.';
 if(blocks.length){models=['انتخاب ساختار نهایی تا تعیین تکلیف مانع حقوقی متوقف بماند'];why='اختلاف یا منع صریح برای اقدام اعلام کرده‌اید، افزایش سرمایه یا تغییر نام قرارداد این مانع را رفع نمی‌کند.';next='موضوع اختلاف و حدود اختیار از مرجع ذی‌صلاح روشن شود، پیش از رفع مانع، ورود قطعی پیشنهاد نمی‌شود.';}
 else if(a.revenue==='support'){models=['تامین منابع عمومی یا حمایتی و قرارداد اجرای برنامه مجاز'];why='هدف، پوشش هزینه آماده‌سازی و تحویل قابل استفاده است، بازده یا بازگشت تجاری فرض نمی‌شود.';}
 else if(a.revenue==='public'){models=b.type==='lhstudy'?['قرارداد خدمات مطالعات و طراحی با منبع پرداخت روشن']:['قرارداد اجرای آماده‌سازی با منبع پرداخت معتبر','تامین مالی قراردادی / EPCF فقط در صورت انطباق دامنه و احراز تعهد بازپرداخت'];why='عایدی از پرداخت کارفرماست، اعتبار، زمان‌بندی پرداخت، تعدیل و پذیرش کار تعیین‌کننده‌اند. EPCF برای هر بسته مطالعات یا عملیات به‌صورت خودکار مناسب نیست.';}
 else if(a.revenue==='sale'){models=['مشارکت قراردادی با تسویه سهم زمین یا واحد مجاز','شرکت پروژه / JV فقط پس از احراز اختیار تشکیل و پذیرش آورده'];why='تسویه غیرنقدی انتخاب شده است، قابلیت انتقال، ارزش‌گذاری، زمان تحویل سهم و امکان نقدکردن آن باید مستقل بررسی شوند.';}
 else if(a.revenue==='mixed'){models=['مشارکت با تسویه ترکیبی نقدی و حقوق یا محصول مجاز'];why='منبع و زمان پرداخت نقدی، ارزش سهم غیرنقدی و مسئول اجرای هر تعهد باید جداگانه مشخص شوند.';}
 else {models=['ساختار همکاری پس از تعیین منبع جبران هزینه قابل انتخاب است'];why='منبع جبران هزینه هنوز تعیین نشده است، پیش از برآورد بازده باید سازوکار پرداخت روشن شود.';}
 for(const q of questions){const effect=q.actions?.[a[q.id]];if(effect){checks.push(effect);decisions.push({question:q.label,answer:q.options.find(o=>o[0]===a[q.id])?.[1]||'',effect,blocking:!!q.block?.includes(a[q.id]),review:!!q.review?.includes(a[q.id])});}}
 if(b.funding!=='own')checks.push('منابع نقدی، تسهیلات و سرمایه شریک احتمالی جدا ثبت شوند، منابع تاییدنشده پول آماده محسوب نمی‌شوند.');
 checks.push('هزینه آماده‌سازی از ارزش زمین و هزینه ساخت مسکن تفکیک شود.','کاربری یا انتقال زمین و واحد فقط با احراز اختیار و اسناد معتبر همان طرح بررسی شود.');
 if(!blocks.length&&decisions.some(d=>d.review))next=decisions.find(d=>d.review).effect+'، سپس بودجه، زمان و ساختار قرارداد بازبینی شوند.';
 return {title:'مسیر قابل بررسی برای '+c.name,models,why,next,finance:a.revenue==='support'?['منابع عمومی یا حمایتی قابل تخصیص و مستند','بودجه نگهداری و تکمیل خدمات، بدون فرض بازده تجاری']:['آورده نقدی شرکا یا پرداخت کارفرما مطابق قرارداد معتبر','آورده غیرنقدی فقط پس از احراز حق و ارزش‌گذاری','تسهیلات احتمالی پس از احراز پذیرش نهاد مالی و توان بازپرداخت'],revenue:getAnswerText(b.group,b.type,'revenue',a.revenue),checks:[...new Set(checks)],decisions,blocked:blocks.length>0,answers:questions.map(q=>({question:q.label,answer:q.options.find(o=>o[0]===a[q.id])?.[1]||'تعیین نشده'}))};
}

function buildSectorGuidance(p){if(p.building?.group==='landhousing')return buildLandHousingGuidance(p);const b=p.building,a=b.answers,c=getAdvisoryConfig(b.group,b.type),checks=[...c.baseChecks],blocked=criticalAnswers(b);let models=[],why='',next='ابتدا اسناد حقوق دارایی، مجوزها و مشخصات فنی را دریافت کنید، سپس تقاضا، هزینه و منبع پرداخت همین خدمت بررسی شود.';
 const social=['flood','streets','fire','ruralroad','natural','protection'].includes(b.type);
 if(blocked.length){models=['پیش‌نیاز ورود حل نشده است، انتخاب قرارداد تا رفع مانع متوقف بماند'];why='بر اساس پاسخ شما، در «'+blocked.map(q=>q.label).join('، ')+'» منع یا مخالفت صریح وجود دارد. نوع قرارداد و سرمایه بیشتر، این مانع را برطرف نمی‌کند.';next='پاسخ مرجع ذی‌صلاح و امکان رفع مانع یا تغییر محدوده طرح را روشن کنید، این وضعیت تایید نشده و فرصت قابل اقدام پیشنهاد نمی‌شود.';}
 else if(a.revenue==='support'){models=['تامین منابع حمایتی / کمک و اجرای برنامه مورد تایید','قرارداد اجرای خدمت و پایش اثر، بدون تعهد بازده تجاری'];why='هدف این مسیر، اثرگذاری و پوشش هزینه است. تا وقتی جریان درآمد معتبر تعریف نشده، دوره بازگشت تجاری محاسبه نمی‌شود.';next='بودجه اجرا و نگهداری، متولی خدمت و شاخص اثرگذاری را مشخص کنید، معیار تصمیم، نتیجه خدمت و کفایت منابع است.';}
 else if(a.phase==='existing'&&a.rehab==='no'){models=['O&M — بهره‌برداری و نگهداری، در صورت انطباق شرح خدمت','اجاره حق استفاده / بهره‌برداری مجاز، برحسب ماهیت دارایی'];why='دارایی موجود است و سرمایه‌گذاری عمده انتخاب نشده، ابتدا قرارداد خدمت و حق‌الزحمه یا اجاره بررسی شود. این مسیر به‌خودی‌خود تامین مالی ساخت نیست.';next='شرح خدمت، مسئول پرداخت هزینه، نیاز احتمالی به سرمایه جدید و شرایط احراز صلاحیت بهره‌بردار مشخص شود.';}
 else if(a.revenue==='saving'){models=['قرارداد مبتنی بر عملکرد و سهم از صرفه‌جوییِ قابل سنجش، منوط به امکان قانونی و تسویه'];why='صرفه‌جویی انتخاب شده است. صرفه‌جویی فیزیکی تنها زمانی مبنای بازپرداخت می‌شود که خط مبنا، اندازه‌گیری، ارزش نقدی و تعهد پرداخت روشن باشد.';next='خط مبنا، روش راستی‌آزمایی و طرف مسئول تسویه صرفه‌جویی را پیش از برآورد بازده نهایی تعیین کنید.';}
 else if(a.revenue==='sale'||(a.revenue==='mixed'&&b.group==='land')){models=['مشارکت در توسعه / تکمیل و تقسیم محصول مجاز','JV — مشارکت در شرکت پروژه، در صورت احراز مجوز'];why='عایدی به عرضه حقوق یا محصول مجاز توسعه وابسته است، ارزش‌گذاری آورده‌ها، حقوق عمومی و امکان عرضه باید پیش از برآورد فروش تایید شوند.';}
 else if(a.revenue==='public'){models=social?['قرارداد اجرای طرح و خدمت با منبع پرداخت مصوب','تامین مالی قراردادی، صرفاً در صورت احراز تعهد بازپرداخت و پذیرش تامین‌کننده مالی']:['DBFO — طراحی، ساخت، تامین مالی و بهره‌برداری، در صورت انطباق دامنه خدمت','مشارکت با خرید خدمت / ظرفیت معتبر، ساختار نهایی پس از احراز اختیار طرف عمومی'];why='منبع بازپرداخت، خریدار خدمت عمومی انتخاب شده است. اختیار تعهد، اعتبار و بودجه و شرایط پرداخت باید مستقل از منافع اجتماعی پروژه احراز شوند.';next='خریدار خدمت، اختیار تعهد، منبع پرداخت و سنجش عملکرد را مستند کنید، بدون این موارد بازده مالی قابل اتکا نیست.';}
 else if(a.phase==='existing'&&a.rehab==='yes'&&a.owner!=='private'){models=['ROT — احیا / بازسازی، بهره‌برداری و انتقال، در صورت انطباق قرارداد','مشارکت در احیا با حق بهره‌برداری مدت‌دار و مجاز'];why='دارایی موجود به سرمایه‌گذاری احیا یا تجهیز نیاز دارد، دوره حق بهره‌برداری و درآمد مجاز باید هزینه احیا و نگهداری را پوشش دهند.';}
 else if(a.owner==='private'){models=['سرمایه‌گذاری در دارایی / شرکت پروژه با مالکیت مجاز','JV — مشارکت سهامی یا قراردادی پس از ارزش‌گذاری آورده‌ها'];if(['industry','energy','agriculture','digital'].includes(b.group))models.push('BOO — ساخت، مالکیت و بهره‌برداری، فقط در صورت مجاز بودن مالکیت و فعالیت');why='عایدی از محصول یا خدمت به مشتری پیش‌بینی شده است، حق فعالیت، بازار، هزینه بهره‌برداری و تقسیم ریسک بین شرکا باید بررسی شوند.';}
 else {models=['BOT — ساخت، بهره‌برداری و انتقال، برای دارایی و درآمد واجد شرایط','مشارکت در توسعه و بهره‌برداری، پس از تعیین حقوق و مجوزها'];why='دریافت درآمد از محصول، استفاده‌کننده یا اجاره ظرفیت مدنظر است، حق دریافت درآمد، تقاضا و تکلیف دارایی در پایان قرارداد باید روشن شوند.';}
 if(!blocked.length&&a.revenue!=='support'&&a.phase==='unfinished'){checks.push('گزارش پیشرفت واقعی، بدهی‌ها، نواقص و هزینه و زمان تکمیل');if(!['sale','mixed','public','saving'].includes(a.revenue))models=['مشارکت در تکمیل و بهره‌برداری، ساختار متناسب با حقوق دارایی موجود'];}
 if(!blocked.length&&a.revenue==='public'&&a.phase==='existing'&&a.rehab==='yes')models=['مشارکت در تامین مالی احیا و خدمت با پرداخت معتبر، متناسب با دارایی موجود'];
 if(a.phase==='any')checks.push('تعیین مرحله واقعی پروژه، قرارداد ساخت برای دارایی موجود خودکار قابل استفاده نیست');
 if(a.owner==='any')checks.push('احراز نوع مالک، اختیار واگذاری و محدودیت‌های مالکیت برای همان فرصت');
 checks.push(({finance:'معرفی و ارزیابی شریک تخصصی اجرا و بهره‌برداری و حقوق نظارت سرمایه‌گذار',develop:'احراز توان مدیریت اجرا، برنامه هزینه و زمان و تضمین تعهدات',operate:'احراز مجوز و توان بهره‌برداری تخصصی و بودجه نگهداری و سرمایه در گردش'})[a.participation]);
 const decisions=[];for(const q of getQuestionsFor(b.group,b.type,a)){const action=q.actions?.[a[q.id]];if(action){checks.push(action);decisions.push({question:q.label,answer:q.options.find(o=>o[0]===a[q.id])?.[1]||'',effect:action,blocking:!!q.block?.includes(a[q.id]),review:!!q.review?.includes(a[q.id])});}}
 if(!blocked.length&&a.revenue!=='support'){const firstReview=decisions.find(x=>x.review);if(firstReview)next=firstReview.effect+'، سپس مدل مالی و ساختار ورود دوباره بررسی شود.';}
 if(b.funding!=='own'){checks.push('مستندکردن منابع قابل تعهد و شرایط واقعی بانک یا شریک، منابع احتمالی به وجه نقد اضافه نشده‌اند');if(!blocked.length)next='میزان منابع نقدی قابل تعهد و شرایط تامین مالی باقی‌مانده را مستند کنید، پیشنهادها بر مبنای پول تاییدنشده تقویت نمی‌شوند.';}
 if(a.rehab==='unknown')checks.push('ارزیابی فنی برای تعیین نیاز به احیا، تجهیز یا تعمیر عمده');
 if(b.group==='heritage'){checks.push('عدم فرض فروش بنا یا تغییر آزادانه کاربری از محل اعطای حق بهره‌برداری');if(!blocked.length&&a.revenue!=='public'&&a.revenue!=='support'&&a.rehab!=='no')models=['مشارکت در مرمت و بهره‌برداری مجاز مدت‌دار','ROT — فقط در صورت انطباق تعهد مرمت، حق بهره‌برداری و تحویل'];}
 const finance=a.revenue==='support'?['آورده حمایتی یا کمک قابل تعهد و مستند','منبع پایدار هزینه نگهداری و پایش، بدون فرض بازپرداخت تجاری']:['آورده نقدی شرکا، آورده غیرنقدی پس از احراز حق، پذیرش و ارزش‌گذاری','بدهی / تسهیلات احتمالی پس از احراز صلاحیت و توان بازپرداخت، بدون احتساب منابع تاییدنشده'];
 if(a.revenue==='saving')finance.push('سرمایه اجرای بهینه‌سازی، بازپرداخت فقط از محل صرفه‌جویی نقدیِ قابل تسویه');
 return {title:'مسیر قابل بررسی برای '+c.name,models,revenue:getAnswerText(b.group,b.type,'revenue',a.revenue),why,finance,checks:[...new Set(checks.filter(Boolean))],next,decisions,blocked:blocked.length>0,answers:getQuestionsFor(b.group,b.type,a).map(q=>({question:q.label,answer:q.options.find(o=>o[0]===a[q.id])?.[1]||'تعیین نشده'}))};
}

function evaluateSectorConditions(r,p){const b=p.building;if(!b)return r;if(b.group==='building')return r;const a=b.answers;for(const q of getQuestionsFor(b.group,b.type,a)){if(q.block?.includes(a[q.id]))r.fail.push('پیش‌نیاز ورود حل نشده: '+q.label);else if(q.review?.includes(a[q.id]))r.missing.push(q.actions?.[a[q.id]]||'بررسی اختصاصی کامل نیست: '+q.label);}
 if(a.revenue==='support'){if(r.project.capital==null)r.missing.push('بودجه موردنیاز برنامه مشخص نیست.');else if(p.capital<r.project.capital)r.fail.push('بودجه حمایتی شما از حداقل نیاز فرضی این نمونه کمتر است.');else r.pass.push('بودجه حمایتی با نیاز فرضی این برنامه سازگار است.');r.warnings.push('در این مسیر، بازگشت تجاری و امتیاز ریسک سرمایه‌گذاری سنجیده نشده است.');}
 return r;
}

function buildBuildingGuidance(p){const b=p.building,a=b.answers,c=buildingConfigs[b.type],checks=[...c.baseChecks];let models=[],revenue=answerLabel('revenue',a.revenue),why='',next='ابتدا اسناد مالکیت و کاربری و امکان اجرای طرح را دریافت کنید، سپس مطالعه بازار و جریان نقدی همین نوع پروژه تهیه شود.';
 if(a.revenue==='support'){models=['تامین منابع حمایتی و قرارداد اجرای خدمت، نیازمند طراحی جداگانه'];why='هدف انتخاب‌شده، اثرگذاری اجتماعی و پوشش هزینه است، بدون درآمد مشخص، مدل بازگشت سرمایه تجاری پیشنهاد نمی‌شود.';next='هدف حمایتی، منبع پایدار پوشش هزینه و متولی بهره‌برداری را مشخص کنید، نمونه‌های بازده‌محور زیر با این هدف تطبیق داده نمی‌شوند.';}
 else if(a.phase==='existing'&&a.rehab==='no'){models=['قرارداد اجاره یا بهره‌برداری خدماتی، خارج از سرمایه‌گذاری ساخت'];why='ساختمان موجود است و سرمایه‌گذاری عمده انتخاب نشده، ابتدا باید روشن شود مشارکت سرمایه‌ای لازم است یا قرارداد خدمت کافی است.';next='شرح خدمت، نیاز واقعی به سرمایه جدید و مسئول پرداخت هزینه بهره‌برداری را مشخص کنید.';}
 else if(a.revenue==='sale'||a.revenue==='mixed'){models=['مشارکت در ساخت / تکمیل','JV — مشارکت در شرکت پروژه، در صورت وجود مجوز'];why='درآمد انتخابی به فروش ساختمان یا ترکیب فروش و اجاره وابسته است، سهم آورده‌ها و زمان فروش باید در قرارداد و مدل مالی روشن باشد.';}
 else if(a.revenue==='public'){models=['BLT — ساخت، اجاره و انتقال، در صورت انطباق تعهدات','DBFO — طراحی، ساخت، تامین مالی و بهره‌برداری، در صورت انطباق خدمت'];why='پرداخت از طرف خریدار خدمت یا دستگاه پیش‌بینی شده است، امکان تعهد بلندمدت، کیفیت خدمت و اعتبار پرداخت‌کننده پیش‌شرط بررسی این ساختارهاست.';checks.push('احراز اختیار تعهد بلندمدت، منبع پرداخت و شرایط تعدیل و کسر پرداخت');}
 else if(a.phase==='existing'&&a.rehab==='yes'&&a.owner!=='private'){models=['ROT — بازسازی، بهره‌برداری و انتقال، در صورت انطباق مالکیت و قرارداد'];why='ساختمان موجود است و به بازسازی عمده نیاز دارد، بازپرداخت از عایدی دوره بهره‌برداری بررسی می‌شود.';}
 else if(a.owner==='private'){models=['مشارکت در توسعه و بهره‌برداری','JV — مشارکت سهامی، در صورت انطباق حقوق و قرارداد'];why='درآمد از اجاره یا خدمت و صاحب پروژه خصوصی انتخاب شده است، مالکیت و تقسیم درآمد باید صریحاً در ساختار مشارکت تعیین شود.';}
