function guidance(p){const s=p.specific,checks=['اسناد معرفی متقاضی، منشا منابع و امکان عملی انتقال ارز یا تجهیزات بررسی شود.','مجوزهای تخصصی، اختیار طرف ایرانی و شیوه مجاز انتخاب شریک یا مجری احراز شود.','مدل مالی، ارز درآمد و هزینه، ریسک تغییر نرخ ارز و مسیر بازگشت منابع جدا بررسی شوند.'],barriers=[],conditions=[];let title='',why='',next='';
