 if(p.route==='contract'){title='بررسی سرمایه‌گذاری قراردادی با بازیافت منابع از پروژه';why='دامنه ساخت، تجهیز یا بهره‌برداری و منبع درآمد، ساختار قرارداد را مشخص می‌کنند. BOT یا سایر عناوین، صرفاً از نوع پروژه قابل انتخاب قطعی نیستند.';checks.push('دامنه تعهدات، دوره قرارداد، حق بهره‌برداری، تقسیم ریسک و تکلیف دارایی در پایان دوره روشن شوند.','در بررسی بند ب ماده ۳ فیپا، بازیافت منابع از عملکرد اقتصادی طرح و شرایط همان بند بررسی شود.');if(s.term!==null)conditions.push('مدت '+s.term+' سال، پیشنهاد شماست، کفایت آن برای بازیافت سرمایه به مطالعه جریان نقدی نیاز دارد.');next='دامنه کار و حقوق بهره‌برداری را با طرف ایرانی روشن کنید و مطالعات امکان‌سنجی و مدل مالی تهیه شود.';}
 if(p.route==='credit'){title='بررسی فاینانس یا اعتبار خارجی، مسیر بدهی پروژه';why='در این مسیر، تامین‌کننده اعتبار لزوماً شریک مالکیت نیست. تعهد بازپرداخت، هزینه واقعی اعتبار و تضامین باید مستقل از قرارداد ساخت تعیین شوند.';checks.push('اعتباردهنده، اعتبارگیرنده، ارز، کارمزدها، نرخ، تنفس، برنامه پرداخت و بازپرداخت در موافقت‌نامه مالی روشن شوند.','پذیرش بانک‌ها، مجوزهای تعهد و تضمین و امکان انتقال و بازپرداخت منابع بررسی شوند.');if(s.guarantee==='state')barriers.push('تضمین دولتی صرفاً مورد درخواست است، وجود اختیار و مجوز صدور آن احراز نشده است.');if(s.tenor!==null&&s.grace!==null)conditions.push('دوره بازپرداخت '+s.tenor+' سال و تنفس '+s.grace+' ماه، جدا ثبت شده‌اند، داخل یا خارج بودن تنفس از دوره کل باید در قرارداد روشن شود.');next='ابتدا پیشنهاد مالی اعتباردهنده و جریان نقدی بازپرداخت دریافت شود، سپس مسیر مجوزها و تضامین بررسی شود.';}
 if(p.route==='execution'){title=s.commitment==='yes'?'همکاری اجرایی همراه با تعهد مالی، نیازمند تفکیک ساختار':'بررسی قرارداد اجرا، تامین تجهیزات یا بهره‌برداری';why=s.commitment==='yes'?'بخش اجرای کار و بخش تامین منابع باید جدا تعریف شوند، برای جزء مالی، مسیر شراکت، سرمایه‌گذاری قراردادی یا اعتبار نیز بررسی شود.':'دریافت حق‌الزحمه در برابر کار، به‌تنهایی سرمایه‌گذاری خارجی محسوب نمی‌شود. قرارداد و منبع پرداخت مبنای بررسی هستند.';checks.push('صلاحیت، سوابق، دامنه خدمات، برنامه اجرا، مسئولیت‌ها، تضمین‌های لازم و نحوه پرداخت مشخص شوند.');if(s.settlement==='operation')checks.push('بازگشت از منافع بهره‌برداری، بررسی ساختار سرمایه‌گذاری قراردادی و حق معتبر بهره‌برداری را لازم می‌کند.');next='دامنه خدمات و تعهد مالی را تفکیک کنید و اسناد معتبر انتخاب مجری و منبع پرداخت دریافت شود.';}
 if(p.rights==='direct')barriers.push('تملک زمین به نام سرمایه‌گذار خارجی در چارچوب فیپا مجاز نیست، پیش از ادامه، ساختار حقوقی و هدف مالکیت بازنگری شود.');
 if(p.rights==='public')checks.push('برای دارایی دولتی یا عمومی، اختیار واگذاری و حقوق قابل اعطا احراز شود، مشارکت به معنی انتقال خودکار مالکیت نیست.');
 if(p.rights==='unknown')barriers.push('حقوق زمین و دارایی مشخص نیست، پیش از انتخاب قطعی روش، سند و اختیار بهره‌برداری بررسی شود.');
 if(p.revenue==='unknown')barriers.push('منبع بازگشت منابع یا پرداخت هنوز معلوم نیست، قابلیت تامین مالی و دوره بازگشت قابل نتیجه‌گیری نیست.');
 if(p.permit!=='reported')checks.push('مجوزهای پروژه هنوز احراز نشده‌اند، مرجع، فهرست مجوزها و وضعیت هرکدام تعیین شود.');
 if(p.license==='issued')checks.push('اصل مجوز فیپا، شرایط، مهلت‌ها، آورده مصوب و سرمایه واقعاً واردشده تطبیق داده شوند، خوداظهاری، تایید مجوز نیست.');else if(p.route!=='execution'||s.commitment!=='no')checks.push('امکان و ضرورت اخذ مجوز فیپا برای برخورداری از حمایت‌ها، جدا از مجوز تخصصی پروژه بررسی شود.');
