function validate(tool,p){for(const q of schemas[tool]){if(q.type==='heading'||q.when&&!q.when(p))continue;const v=p[q.id];if(q.required&&(v===null||v===''||Array.isArray(v)&&v.length===0))return 'لطفاً «'+q.label+'» را تکمیل کنید.';if(q.type==='number'&&v!==null){if(!Number.isFinite(v)||v<(q.min??0)||q.positive&&v===0||q.integer&&!Number.isInteger(v))return 'مقدار «'+q.label+'» معتبر نیست، واحد و مثبت یا صحیح بودن عدد را بررسی کنید.';}if(q.type==='select'&&!q.options.some(([key])=>key===v))return 'گزینه «'+q.label+'» معتبر نیست.';if(q.type==='multi'&&v.some(x=>!q.options.some(([key])=>key===x)))return 'گزینه‌های انتخابی معتبر نیستند.';}
 if(tool==='renewal'&&p.displacement==='yes'&&p.households===0)return 'برای اسکان موقت، تعداد خانوار باید بیشتر از صفر باشد، اگر مشخص نیست خالی بگذارید.';
 if(tool==='profile'&&p.certificateNo&&!p.issuer)return 'برای گواهینامه دارای شماره، مرجع صادرکننده را نیز مشخص کنید.';
 return '';}
